def luqum_replace_field(query: Item, replacer: Callable[[str], str]) -> str:
    """
    Replaces the name of every SearchField in the query tree using `replacer`,
    and returns the modified query as a string.

    :param query: Parsed luqum tree to modify in place
    :param replacer: Function taking a field name and returning the new name
    """
    for node, _ in luqum_traverse(query):
        if isinstance(node, SearchField):
            node.name = replacer(node.name)
