def template_config_variables(template):
    """Return the config variables used in the template."""
    from jinja2 import nodes
    unvisted = [environment.parse(template)]
    result = set()
    while unvisted:
        node = unvisted.pop()
        if not isinstance(node, nodes.Getattr):
            unvisted.extend(node.iter_child_nodes())
            continue
        attrlist = []
        cur = node
        while isinstance(cur, nodes.Getattr):
            attrlist.append(cur.attr)
            cur = cur.node
        if isinstance(cur, nodes.Name) and cur.name == 'conf':
            result.add('.'.join(reversed(attrlist)))
        else:
            unvisted.append(cur)
    from qutebrowser.config import config
    for name in result:
        config.instance.ensure_has_opt(name)
    return frozenset(result)


